import {pieceSize} from './castle-scale.mjs';
import {initSettings} from './castle-settings.mjs';
import roomImage from './castle-room-data.mjs';
import {loadAssets} from './display-api.mjs';
const $=s=>document.querySelector(s),room=$('#room'),picker=$('#picker'),bannerDialog=$('#bannerDialog');
$('#background').src=roomImage;
const spots=[['Upper left alcove',24.6,37.47,13,10],['Upper centre alcove',42.6,37.79,13,10],['Upper right alcove',60.3,38.26,13,10],['Lower left shelf',24.5,48.69,13,9],['Lower centre shelf',42.7,49.11,13,9],['Lower right shelf',61,49.27,13,9],['Left mantel',29.5,57.76,15,8],['Right mantel',51,57.76,15,8],['Window cabinet',10,64.83,14,10],['Right console',72.4,64.78,15,10]];
const key='edge-castle-room-v2';let state={pieces:Array(10).fill(null),name:'',emblem:''},products=[],assets={},selected=0,editing=true;
try{const s=JSON.parse(localStorage.getItem(key));if(s&&Array.isArray(s.pieces)&&s.pieces.length===10)state={pieces:s.pieces,name:typeof s.name==='string'?s.name.slice(0,32):'',emblem:['','⚜','♜','♞','✦'].includes(s.emblem)?s.emblem:''}}catch{}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#status').textContent='Saved on this browser.'}catch{$('#status').textContent='Browser storage unavailable. Changes last for this visit.'}}
function renderBanner(){$('.crest').textContent=state.emblem;$('.banner-name').textContent=state.name}
function render(){spots.forEach((s,i)=>{const b=document.querySelector('[data-slot="'+i+'"]');b.replaceChildren();const p=products.find(p=>p.id===state.pieces[i]);b.classList.toggle('filled',!!p);if(p){const size=pieceSize(p,assets[p.id],Number(room.dataset.mantel)||200,i>7?1.04:1);const im=new Image();im.src='/'+assets[p.id].src.replace(/^\//,'');im.alt=p.name;if(size){im.style.width=(size.width/(1280*s[3]/100)*100)+'%';im.style.height=(size.height/(1908*s[4]/100)*100)+'%';b.style.setProperty('--contact-width',Math.min(size.width/(1280*s[3]/100)*75,100)+'%')}else{im.hidden=true;b.title='Catalogue dimensions missing — choose another piece'}b.append(im)}const plus=document.createElement('span');plus.className='plus';plus.textContent='+';b.append(plus);b.setAttribute('aria-label',s[0]+(p?': '+p.name+'. Change sculpture':': Add sculpture'))});renderBanner()}

spots.forEach(([name,x,y,w,h],i)=>{const b=document.createElement('button');b.className='spot';b.dataset.slot=i;b.style.cssText=`left:${x}%;top:${y-h}%;width:${w}%;height:${h}%`;b.onclick=()=>{selected=i;$('#spotTitle').textContent=name;$('#search').value='';list();picker.showModal();$('#search').focus()};room.append(b)});
function list(){const q=$('#search').value.trim().toLowerCase(),matches=products.filter(p=>p.name.toLowerCase().includes(q));$('#choices').replaceChildren();for(const p of matches){const b=document.createElement('button'),im=new Image(),label=document.createElement('span');im.src='/'+assets[p.id].src.replace(/^\//,'');im.alt='';im.loading='lazy';label.textContent=p.name+(p.h?' · '+p.h+' cm H × '+p.w+' cm W × '+p.d+' cm D':' · dimensions unavailable');b.disabled=!p.h;b.append(im,label);b.onclick=()=>{state.pieces[selected]=p.id;render();save();picker.close()};$('#choices').append(b)}if(!matches.length){const p=document.createElement('p');p.className='empty';p.textContent=products.length?'No matching sculptures. Try another name.':'The catalogue is unavailable. Please refresh to try again.';$('#choices').append(p)}}
$('#search').oninput=list;$('#remove').onclick=()=>{state.pieces[selected]=null;render();save();picker.close()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function setEditing(value){editing=value;room.classList.toggle('editing',value);$('#edit').setAttribute('aria-pressed',String(value));document.querySelectorAll('.spot,#bannerHit').forEach(b=>b.tabIndex=value?0:-1)}
$('#edit').onclick=()=>{document.body.classList.remove('immersive');$('#view').setAttribute('aria-pressed','false');$('#view').textContent='View room';setEditing(!editing)};
$('#view').onclick=()=>{const on=document.body.classList.toggle('immersive');$('#view').setAttribute('aria-pressed',String(on));$('#view').textContent=on?'Exit view':'View room';setEditing(!on)};
function openBanner(){$('#house').value=state.name;$('#emblem').value=state.emblem;bannerDialog.showModal()}$('#banner').onclick=openBanner;$('#bannerHit').onclick=openBanner;
$('#bannerForm').onsubmit=e=>{e.preventDefault();state.name=$('#house').value.trim();state.emblem=$('#emblem').value;renderBanner();save();bannerDialog.close()};$('#blank').onclick=()=>{state.name='';state.emblem='';renderBanner();save();bannerDialog.close()};
$('#sample').disabled=true;$('#sample').onclick=()=>{const names=['Gorilla Bust','Lion Bust','Highland Cow','Venus','Wolf Bust','Horse Bust','Sea Turtle','Chameleon','Baby Chimpanzee','Frog'];const used=new Set();state.pieces=names.map(n=>{const p=products.find(p=>p.name===n&&!used.has(p.id))||products.find(p=>!p.name.startsWith('Miniature')&&p.name.toLowerCase().includes(n.toLowerCase())&&!used.has(p.id))||products.find(p=>!used.has(p.id));if(p)used.add(p.id);return p?.id||null});render();save()};
initSettings(room,render);
render();try{const loaded=await loadAssets();assets=loaded.assets;products=[...loaded.catalog.values()].filter(p=>assets[p.id]?.src).sort((a,b)=>a.name.localeCompare(b.name));render();$('#sample').disabled=!products.length;$('#status').textContent='Tap a display spot to begin.'}catch{$('#status').textContent='Could not load sculptures. Refresh to try again.'}
